//! Inert candidate reads are isolated from the real App editor and layout.
use super::*;
struct Fixture(std::path::PathBuf);impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{(0..app.document.nodes.len()).find(|&n|app.document.attr(n,"id")==Some(id)).unwrap()}
#[test]
fn inert_control_eligibility_actual_app_reads_drive_paint_without_validation_or_editor_changes(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-inert-eligibility-{}.html",std::process::id())));std::fs::write(&file.0,r#"<!doctype html><style>#paint{position:absolute;left:420px;top:160px;width:40px;height:30px;background:#114455}#paint.done{background:#cc2244}#stable{position:absolute;left:420px;top:100px}</style><form><input id=neighbor name=q value=Seed required></form><button id=go name=go type=button>Check inert</button><a id=stable href=#target>Go</a><div id=paint></div><div id=target></div><script>document.getElementById('go').onclick=function(){var doc=document.implementation.createHTMLDocument('inert'),f=doc.createElement('fieldset'),l=doc.createElement('legend'),x=doc.createElement('input'),list=doc.createElement('datalist');f.disabled=true;f.appendChild(l);l.appendChild(x);x.required=true;x.addEventListener('invalid',function(){throw 'metadata dispatched';});if(!x.willValidate)throw 'first legend';f.appendChild(x);if(x.willValidate)throw 'disabled';list.appendChild(x);if(x.willValidate)throw 'datalist';doc.body.appendChild(x);if(!x.willValidate)throw 'moved';document.getElementById('paint').className='done';document.title='Inert candidate';};</script>"#).unwrap();let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);let neighbor=node(&app,"neighbor");let go=node(&app,"go");let stable=node(&app,"stable");app.forms.script_set_value(neighbor,"neighbor edit").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}
 let before=app.draw();let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let r=app.page.controls.iter().find(|r|r.node==neighbor).unwrap();let rect=(r.x,r.y,r.width,r.height);let r=app.page.controls.iter().find(|r|r.node==go).unwrap();let(x,y)=(r.x+r.width/2,app.content_top()+r.y+r.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);assert_eq!(app.document.title,"Inert candidate");assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert!(app.status.is_empty());let painted=app.draw();let pixel=(app.content_top()+170)as usize*painted.width+430;assert_eq!(painted.pixels[pixel],0xcc2244);assert_ne!(before.pixels[pixel],painted.pixels[pixel]);let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("neighbor edit".into(),5,2,1));let r=app.page.controls.iter().find(|r|r.node==neighbor).unwrap();assert_eq!((r.x,r.y,r.width,r.height),rect);assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!((app.raw.clone(),app.location.clone(),app.script_epoch),(raw,location,epoch));assert!(matches!(app.focus,Focus::Control(n)if n==go));
}
